describe('command name and alias clashes', () => {
  test('when .command() reuses name then throw', () => {
    const program = new commander.Command();
    program.command('sub');
    expect(() => program.command('sub')).toThrow('cannot add command');
  });

  test('when .command() name matches alias then throw', () => {
    const program = new commander.Command();
    program.command('sub').alias('s');
    expect(() => program.command('s')).toThrow('cannot add command');
  });

  test('when .addCommand() reuses name then throw', () => {
    const program = new commander.Command();
    program.command('sub');
    expect(() => program.addCommand(new commander.Command('sub'))).toThrow('cannot add command');
  });

  test('when .addCommand() alias matches existing then throw', () => {
    const program = new commander.Command();
    program.command('sub');
    const other = new commander.Command('other').alias('sub');
    expect(() => program.addCommand(other)).toThrow('cannot add command');
  });

  test('when .alias() matches other command name then throw', () => {
    const program = new commander.Command();
    program.command('sub');
    expect(() => program.command('other').alias('sub')).toThrow('cannot add alias');
  });

  test('when .alias() matches other alias then throw', () => {
    const program = new commander.Command();
    program.command('a').alias('x');
    expect(() => program.command('b').alias('x')).toThrow('cannot add alias');
  });
});
